records.raw:
SELECT (COUNT(DISTINCT cd.mql_id) * 100.0 / COUNT(DISTINCT mql.mql_id)) AS conversion_rate
FROM marketing_qualified_leads mql
LEFT JOIN closed_deals cd ON mql.mql_id = cd.mql_id;

